import React from "react";
import { Check } from "@airbus/icons/react";
import Button from "../Button";
import Inline from "../Inline";
import Typography from "../Typography";
import Stepper, {
  Step,
  StepContent,
  StepHeader,
  StepSubSteps,
} from "./Stepper";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Stepper> = {
  id: "Components/Stepper",
  title: "Components/Stepper",
  component: Stepper,
};

export default meta;
type Story = StoryObj<typeof Stepper>;

export const Basic: Story = {
  tags: ["visual-test"],
  args: {
    horizontal: true,
    activeStep: 1,
  },
  parameters: { docs: { source: { type: "code" } } },
  render: (args) => {
    const stepCount = 4;
    let activeStep = 2;
    return (
      <div>
        <Stepper {...args}>
          {[...Array(stepCount).keys()].map((stepIndex) => (
            <Step
              key={`step-${stepIndex}`}
              icon={activeStep > stepIndex && <Check />}
            >
              <StepHeader>{`Step ${stepIndex + 1}`}</StepHeader>
            </Step>
          ))}
        </Stepper>
      </div>
    );
  },
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const stepCount = 4;
    const [activeStep, setActiveStep] = React.useState(1);
    return (
      <>
        <Stepper
          activeStep={activeStep}
          horizontal
          onStepClick={(index) => setActiveStep(index)}
        >
          {[...Array(stepCount).keys()].map((stepIndex) => (
            <Step
              key={`step-${stepIndex}`}
              icon={activeStep > stepIndex && <Check />}
            >
              <StepHeader>{`Step ${stepIndex + 1}`}</StepHeader>
            </Step>
          ))}
        </Stepper>
        <Inline spacing="2-x" align="center">
          <Button
            variant="ghost"
            disabled={activeStep === 0}
            onClick={() => setActiveStep(activeStep - 1)}
          >
            BACK
          </Button>
          <Button
            variant="primary"
            disabled={activeStep === stepCount - 1}
            onClick={() => setActiveStep(activeStep + 1)}
          >
            NEXT
          </Button>
        </Inline>
      </>
    );
  },
};

export const NonLinear: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const stepCount = 4;
    const [activeStep, setActiveStep] = React.useState(0);
    const [completed, setCompleted] = React.useState(new Map());
    const handleCompleteStep = () => {
      setCompleted(new Map(completed.set(activeStep, true)));
      if (activeStep < stepCount - 1) setActiveStep(activeStep + 1);
    };
    return (
      <div>
        <Stepper
          activeStep={activeStep}
          horizontal
          nonLinear
          onStepClick={(index) => setActiveStep(index)}
        >
          {[...Array(stepCount).keys()].map((stepIndex) => (
            <Step
              key={`step-${stepIndex}`}
              icon={completed.get(stepIndex) && <Check />}
              disabled={stepIndex === 1}
            >
              <StepHeader>{`Step ${stepIndex + 1}`}</StepHeader>
            </Step>
          ))}
        </Stepper>
        <Inline spacing="2-x" align="center">
          <Button
            variant="ghost"
            disabled={activeStep === 0}
            onClick={() => setActiveStep(activeStep - 1)}
          >
            BACK
          </Button>
          <Button
            variant="primary"
            disabled={activeStep === stepCount - 1}
            onClick={() => setActiveStep(activeStep + 1)}
          >
            NEXT
          </Button>
          <Button
            variant="secondary"
            disabled={completed.get(activeStep)}
            onClick={handleCompleteStep}
          >
            COMPLETE STEP
          </Button>
        </Inline>
      </div>
    );
  },
};

