export const WithSubSteps: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const stepCount = 4;
    const subStepCount = 3;
    const [activeStep, setActiveStep] = React.useState(1);
    const [activeSubStep, setActiveSubStep] = React.useState(1);
    const handleBack = () => {
      if (activeSubStep > 0) setActiveSubStep(activeSubStep - 1);
      else {
        setActiveSubStep(subStepCount - 1);
        setActiveStep(activeStep - 1);
      }
    };
    const handleNext = () => {
      if (activeSubStep < subStepCount - 1) setActiveSubStep(activeSubStep + 1);
      else {
        setActiveSubStep(0);
        setActiveStep(activeStep + 1);
      }
    };
    return (
      <Inline spacing="6-x" alignY="start">
        <Stepper
          activeStep={activeStep}
          onStepClick={(index) => setActiveStep(index)}
        >
          {[...Array(stepCount).keys()].map((stepIndex) => (
            <Step
              key={`step-${stepIndex}`}
              icon={activeStep > stepIndex && <Check />}
            >
              <StepHeader>{`Step ${stepIndex + 1}`}</StepHeader>
              {activeStep === stepIndex && (
                <StepSubSteps
                  activeSubStep={activeSubStep}
                  onSubStepClick={(index) => setActiveSubStep(index)}
                >
                  {[...Array(subStepCount).keys()].map((subStepIndex) => (
                    <Step key={`substep-${subStepIndex}`}>
                      <StepHeader>{`Sub Step ${subStepIndex + 1}`}</StepHeader>
                    </Step>
                  ))}
                </StepSubSteps>
              )}
            </Step>
          ))}
        </Stepper>
        <div style={{ flex: 1 }}>
          <Typography variant="h3">
            {`Step ${activeStep + 1}`} / {`Sub Step ${activeSubStep + 1}`}
          </Typography>
          <p>
            External content displayed conditionnaly depending on current active
            step / sub step
          </p>
          <Inline spacing="2-x">
            <Button
              variant="ghost"
              disabled={activeStep === 0 && activeSubStep === 0}
              onClick={handleBack}
            >
              BACK
            </Button>
            <Button
              variant="primary"
              disabled={
                activeStep === stepCount && activeSubStep === subStepCount - 1
              }
              onClick={handleNext}
            >
              NEXT
            </Button>
          </Inline>
        </div>
      </Inline>
    );
  },
};
